      "type": "string",
      "title": "Offer a handoff for a new task",
      "description": "When context passes CLAUDE_CTX_GUARD_TOKENS (150k by default), Haiku judges whether a prompt is an unrelated new task. suggest: the prompt is sent as usual and a handoff is offered above the prompt box when it is judged new; block: the prompt is held and you choose; off: no judging (default). Turn it on for a while with /session-keeper on handoff_gate (suggest).",
      "options": [
        "suggest",
        "block",
        "off"
      ],
      "default": "off"
    },
    "away_handoff": {
      "type": "boolean",
      "title": "Offer a handoff when the cache has expired",
      "description": "When context is over the threshold and the cache has expired, the prompt is held and you choose to hand off or stay; with a 1h TTL the last keep-warm writes the handoff summary ahead of time instead. Off by default; turn it on for a while with /session-keeper on away_handoff.",
      "default": false
    },
    "progress_resume": {
      "type": "boolean",
      "title": "Bring progress into a new session",
      "description": "The first prompt of a new session gets .claude/progress.md attached (under 24 hours old, not written by this session, not given before).",
      "default": true
    }
  }
}

